function drawProjectile(p){ctx.save();ctx.shadowBlur=22;ctx.shadowColor=p.color;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.35;ctx.beginPath();ctx.ellipse(p.x-p.vx*.025,p.y,p.r*2.7,p.r*.7,0,0,Math.PI*2);ctx.fill();ctx.restore()}
function breakObject(o){if(o.broken)return;o.broken=true;roundStats.destruct++;save.shards+=2;persist();for(let i=0;i<16;i++)particles.push({x:o.x+rand(-o.w/2,o.w/2),y:o.y-o.h/2+rand(-o.h/2,o.h/2),vx:rand(-190,190),vy:rand(-270,30),life:rand(.45,1.1),max:1.1,color:i%2?o.color:'#e8fbff',size:rand(3,10)});shake=8;notify('+2 RIFT SHARDS · COVER SHATTERED');populate()}
